body.t-blueprint .bg-fx {
  background-image:
    linear-gradient(rgba(255,255,255,.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.055) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.028) 1px, transparent 1px);
  background-size: 120px 120px, 120px 120px, 24px 24px, 24px 24px;
}
body.t-blueprint .section-tag { background: transparent; border-style: dashed; }
body.t-blueprint .section-tag::before { content: "[ "; color: var(--text-2); }
body.t-blueprint .section-tag::after { content: " ]"; color: var(--text-2); }
body.t-blueprint .section-title { font-weight: 400; letter-spacing: 1px; }
body.t-blueprint .section-title::after { content: ""; display: block; height: 1px; margin-top: 12px; background: repeating-linear-gradient(90deg, var(--border) 0 10px, transparent 10px 16px); }
body.t-blueprint .card, body.t-blueprint .post, body.t-blueprint .fact, body.t-blueprint .contact-card { border-style: dashed; border-width: 1px; }
body.t-blueprint .card:hover, body.t-blueprint .post:hover, body.t-blueprint .contact-card:hover { border-style: solid; border-color: var(--accent); }
body.t-blueprint .card.featured { border-style: solid; border-color: var(--accent); }
body.t-blueprint .card.featured::before { content: "FIG.01 ★"; background: var(--accent); color: #16324f; border-radius: 0; font-weight: 700; }
body.t-blueprint .hero h1 { font-weight: 400; }
body.t-blueprint .hero h1::after { content: ""; display: block; width: 220px; height: 10px; margin-top: 14px; background: repeating-linear-gradient(90deg, var(--accent) 0 2px, transparent 2px 12px); }
body.t-blueprint .btn { border: 1px solid var(--border); font-weight: 400; letter-spacing: 1px; }
body.t-blueprint .btn-primary { background: var(--accent); color: #16324f; border-color: var(--accent); font-weight: 700; }
body.t-blueprint .btn-primary:hover { box-shadow: 0 0 0 3px rgba(255,209,102,.3); }
body.t-blueprint .bar-track { border: 1px solid var(--border); background: transparent; height: 12px; }
body.t-blueprint .bar-fill { background: repeating-linear-gradient(-45deg, var(--accent-2) 0 6px, transparent 6px 9px); }
body.t-blueprint .bar-row:first-child .bar-fill { background: repeating-linear-gradient(-45deg, var(--accent) 0 6px, transparent 6px 9px); }
